'use strict';
// Kódex: symboly, osobnosti a pojmy, ktoré hráč odomyká v leveloch (obsah z prednášok 1–3).

const CODEX = [
  // ---------- Level 1: Komplexný prístav ----------
  { id: 'euler', level: 1, type: 'osobnost', sym: '👤', name: 'Leonhard Euler (1707–1783)', text: 'Švajčiarsky matematik; zápisy e, i, f(x), Σ. Jeho vzorec spája exponenciálu s kosínusom a sínusom — dnes „jazyk fázy“ v kvantovej mechanike.' },
  { id: 'i', level: 1, type: 'symbol', sym: 'i', name: 'imaginárna jednotka', text: 'Číslo, ktorého štvorec je −1. Násobenie i = otočenie o 90° v komplexnej rovine.', do: 'Pamätaj: i · i = otočenie o 180° = −1.', dont: 'Nepleť si i (číslo) s indexom i v α<sub>i</sub> či δ<sub>ij</sub>.' },
  { id: 'eiphi', level: 1, type: 'symbol', sym: 'e<sup>iφ</sup>', name: 'fázový faktor', text: 'Komplexné číslo s veľkosťou 1 — „ručička hodín“ otočená o uhol φ.', do: 'Predstav si bod na jednotkovej kružnici.', dont: 'Nie je to fyzikálne otáčanie častice.' },
  { id: 'amp', level: 1, type: 'pojem', sym: 'α', name: 'pravdepodobnostná amplitúda', text: 'Komplexné číslo pri bázovom stave. Má veľkosť aj fázu.', do: 'Interferujú (sčítavajú sa) amplitúdy.', dont: 'Amplitúda NIE JE pravdepodobnosť.' },
  { id: 'abs2', level: 1, type: 'symbol', sym: '|α|²', name: 'štvorec absolútnej hodnoty', text: 'Z amplitúdy urobí pravdepodobnosť (Bornovo pravidlo). Fázu „nevidí“.', do: '|α|² = α · α*', dont: '|α|² ≠ α² pre komplexné α (pre α = i: α² = −1, |α|² = 1).' },
  { id: 'ReIm', level: 1, type: 'symbol', sym: 'Re, Im', name: 'reálna a imaginárna časť', text: 'Dve osi komplexnej roviny. Interferenčný člen obsahuje Re(A₁A₂*).', dont: 'V QM nezahadzuj imaginárnu časť amplitúdy — nesie fázu.' },
  { id: 'interf', level: 1, type: 'pojem', sym: '∿', name: 'interferencia', text: 'Najprv sčítaj amplitúdy, až potom umocni. Podľa relatívnej fázy sa výsledok zosilní (konštruktívne) alebo vyruší (deštruktívne).', dont: 'Samotné slovo „interferencia“ nevysvetľuje kvantovú výhodu — interferujú aj vlny na vode.' },
  { id: 'conj', level: 1, type: 'symbol', sym: 'z*', name: 'komplexne združené číslo', text: 'Zrkadlo podľa reálnej osi: a + ib → a − ib. z·z* = |z|².', dont: 'Hviezdička tu nie je násobenie.' },

  // ---------- Level 2: Sternova–Gerlachova pec ----------
  { id: 'stern', level: 2, type: 'osobnost', sym: '👤', name: 'Otto Stern (1888–1969)', text: 'Majster molekulových zväzkov. 1922 so W. Gerlachom: atómy striebra sa v nehomogénnom poli rozdelili na DVE stopy. Nobelova cena 1943.' },
  { id: 'gerlach', level: 2, type: 'osobnost', sym: '👤', name: 'Walther Gerlach (1889–1979)', text: 'Uskutočnil experiment vo Frankfurte 1922. Súvis so spinom elektrónu (Uhlenbeck, Goudsmit 1925) sa ukázal až neskôr.' },
  { id: 'Sz', level: 2, type: 'symbol', sym: 'S<sub>z</sub>', name: 'z-ová zložka spinu', text: 'Projekcia spinu na os zvolenú prístrojom. Pre spin ½ len dve hodnoty.', do: 'Os z vyberá magnet — S<sub>x</sub> je rovnako legitímna.', dont: 'Spin pred meraním „neukazoval“ hore ani dole ako šípka.' },
  { id: 'hbar', level: 2, type: 'symbol', sym: 'ħ', name: 'h s čiarou (redukovaná Planckova konštanta)', text: 'h/2π — prirodzená jednotka momentu hybnosti. Výsledky merania spinu ½: +ħ/2 a −ħ/2.', dont: 'Nepleť si ħ a h (líšia sa o 2π). Nie je to „htrans“.' },
  { id: 'spinhalf', level: 2, type: 'symbol', sym: 's = ½', name: 'spin ½', text: 'Označenie DRUHU kvantového spinu (elektrón, protón). Dve možné projekcie.', dont: '½ neznamená polovičnú otáčku ani polovičnú rýchlosť rotácie.' },
  { id: 'basisq', level: 2, type: 'pojem', sym: '🧭', name: 'meracia báza je súčasťou otázky', text: 'Výsledok závisí od toho, v akej osi meriame. Istota v osi z neznamená istotu v osi x.', dont: 'Nezávisí od „vedomia pozorovateľa“, ale od experimentálneho usporiadania.' },
  { id: 'ket0', level: 2, type: 'symbol', sym: '|0⟩ ≡ |+z⟩', name: 'bázový stav „spin hore“', text: 'Číslice 0 a 1 zodpovedajú dvom vylučujúcim sa výsledkom merania.', dont: '|0⟩ nie je nulový vektor a |0⟩, |1⟩ nie sú opačné šípky — sú KOLMÉ.' },

  // ---------- Level 3: Blochovo observatórium ----------
  { id: 'bloch', level: 3, type: 'osobnost', sym: '👤', name: 'Felix Bloch (1905–1983)', text: 'Prvý doktorand Heisenberga, Nobelova cena 1952 za NMR, prvý riaditeľ CERN. Jeho rovnice pre magnetizáciu viedli k Blochovej sfére.' },
  { id: 'sphere', level: 3, type: 'pojem', sym: '🌐', name: 'Blochova sféra', text: 'Čistý stav qubitu = bod na povrchu, zmiešaný = vnútri. Sever |0⟩, juh |1⟩, rovník |±⟩, |±i⟩.', dont: 'Nie je to priestor laboratória ani os rotujúcej guľôčky. Ortogonálne stavy sú na sfére PROTIĽAHLÉ.' },
  { id: 'H', level: 3, type: 'symbol', sym: 'H', name: 'Hadamardovo hradlo', text: 'Rotácia o 180° okolo osi medzi x a z. Vymieňa osi x ↔ z, y → −y. H·H = I.', do: 'Povedz „unitárna zmena bázy“.', dont: '„Vytvára superpozíciu“ je neúplné — závisí od bázy. Nepleť s Hamiltoniánom Ĥ.' },
  { id: 'XYZ', level: 3, type: 'symbol', sym: 'X, Y, Z', name: 'Pauliho hradlá', text: 'Rotácie o 180° okolo osí x, y, z. X = preklopenie bitu, Z = preklopenie fázy.', dont: 'X hradlo nie je súradnica x.' },
  { id: 'ST', level: 3, type: 'symbol', sym: 'S, T', name: 'fázové hradlá', text: 'Rotácie okolo z o 90° (S) a 45° (T). Menia relatívnu fázu, nie pravdepodobnosti v Z-báze.' },
  { id: 'globalph', level: 3, type: 'pojem', sym: '∼', name: 'rovnosť až na globálnu fázu', text: 'Stavy líšiace sa spoločným faktorom e<sup>iγ</sup> sú fyzikálne totožné: −iX ∼ X.', dont: '∼ neznamená „viem to premeniť na“. Globálna ≠ relatívna fáza.' },
  { id: 'relph', level: 3, type: 'pojem', sym: 'φ', name: 'relatívna fáza', text: 'Fázový rozdiel medzi α a β. |+⟩ a |−⟩ majú rovnaké P(0), P(1), ale inú fázu — rozlíši ich meranie v X-báze.', dont: 'Relatívnu fázu nemožno zanedbať.' },
  { id: 'thetaphi', level: 3, type: 'symbol', sym: 'θ, φ', name: 'uhly na Blochovej sfére', text: 'θ určuje pravdepodobnosti v Z-báze, φ je relatívna fáza. V zápise stavu vystupuje θ/2.' },
  { id: 'unitary', level: 3, type: 'pojem', sym: 'U', name: 'unitárna operácia = rotácia', text: 'Každé jednoqubitové hradlo je (až na globálnu fázu) rotácia Blochovej sféry. Zachováva dĺžku Blochovho vektora.', dont: 'Neplatí „pod povrchom neunitárne“: unitárne operácie otáčajú aj zmiešané stavy.' },

  // ---------- Level 4: Chrám interferencie ----------
  { id: 'feynman', level: 4, type: 'osobnost', sym: '👤', name: 'Richard Feynman (1918–1988)', text: 'Nobelova cena 1965 (QED). 1981: prírodu treba simulovať kvantovými systémami — zrod myšlienky kvantového počítača.' },
  { id: 'rho', level: 4, type: 'symbol', sym: 'ρ', name: 'matica hustoty (ró)', text: 'Úplný opis stavu vrátane zmesí. Diagonála = populácie, mimodiagonála = koherencie.', dont: 'Je to grécke ró, nie písmeno p.' },
  { id: 'mix', level: 4, type: 'symbol', sym: 'I/2', name: 'maximálne zmiešaný stav', text: 'Stred Blochovej sféry. 50/50 v akejkoľvek báze, žiadne koherencie.', dont: 'Nie je to |+⟩ — tá dá v X-báze vždy „+“.' },
  { id: 'coh', level: 4, type: 'pojem', sym: '≋', name: 'koherencia', text: 'Pevný fázový vzťah medzi zložkami; „palivo“ interferencie. Meranie v báze ju zničí.' },
  { id: 'supmix', level: 4, type: 'pojem', sym: '⚖', name: 'superpozícia ≠ zmes', text: 'V Z-báze dávajú rovnaké štatistiky, ale len superpozícia interferuje (H·H → 0 s istotou).', dont: 'Superpozícia nie je „nevieme, v ktorom stave je“.' },
  { id: 'deco', level: 4, type: 'pojem', sym: '🌫', name: 'dekoherencia', text: 'Prostredie „odmeria“ fázu a mimodiagonálne prvky ρ miznú. Blochov vektor sa zmršťuje dovnútra.', dont: 'Sama nevytvára konkrétny výsledok merania.' },
  { id: 'dagger', level: 4, type: 'symbol', sym: '†', name: 'dýka — hermitovské združenie', text: 'Transpozícia + komplexné združenie. Unitárne U: U·U† = I.', dont: '† ≠ transpozícia T, † ≠ *.' },

  // ---------- Level 5: Diracova knižnica ----------
  { id: 'dirac', level: 5, type: 'osobnost', sym: '👤', name: 'Paul Dirac (1902–1984)', text: 'Diracova rovnica (1928) → antihmota; Nobelova cena 1933; bra-ket notácia (1939). Povestne málovravný: „1 dirac = 1 slovo za hodinu“.' },
  { id: 'ket', level: 5, type: 'symbol', sym: '|ψ⟩', name: 'ket', text: 'Abstraktný kvantový stav (stĺpcový vektor).', dont: 'Ket nie je číslo ani funkcia — ψ(x) je až jeho reprezentácia.' },
  { id: 'bra', level: 5, type: 'symbol', sym: '⟨ψ|', name: 'bra', text: 'Duálny (hermitovsky združený) vektor — riadok. „Kladie otázku.“', dont: 'Bez komplexného združenia koeficientov je to chyba.' },
  { id: 'braket', level: 5, type: 'symbol', sym: '⟨φ|ψ⟩', name: 'bra-ket (skalárny súčin)', text: 'KOMPLEXNÉ ČÍSLO — amplitúda prekrytia dvoch stavov.', dont: 'Nie je to pravdepodobnosť — tou je |⟨φ|ψ⟩|².' },
  { id: 'ketbra', level: 5, type: 'symbol', sym: '|ψ⟩⟨φ|', name: 'ket-bra', text: 'OPERÁTOR (matica). |ψ⟩⟨ψ| je projektor = ρ čistého stavu.', dont: 'Poradie mení typ objektu: ⟨φ|ψ⟩ je číslo, |ψ⟩⟨φ| je operátor.' },
  { id: 'hat', level: 5, type: 'symbol', sym: 'Â', name: 'strieška = operátor', text: 'Pozorovateľná veličina ako operátor (Ĥ, p̂, Ẑ).', dont: 'Pri osiach (x̂, n̂) znamená strieška jednotkový vektor.' },
  { id: 'expect', level: 5, type: 'symbol', sym: '⟨ψ|Â|ψ⟩', name: 'stredná hodnota', text: 'Priemer mnohých meraní na rovnako pripravených systémoch.', dont: 'Nemusí byť možným výsledkom jedného merania (⟨Z⟩ = 0 pre |+⟩).' },
  { id: 'tensor', level: 5, type: 'symbol', sym: '⊗', name: 'tenzorový súčin', text: 'Skladá systémy: |0⟩ ⊗ |1⟩ = |01⟩. Dimenzie sa násobia.', dont: '⊗ nie je obyčajné ani vektorové (×) násobenie.' },
  { id: 'kron', level: 5, type: 'symbol', sym: 'δ<sub>ij</sub>', name: 'Kroneckerova delta', text: '1 ak i = j, inak 0. Ortonormálna báza: ⟨i|j⟩ = δ<sub>ij</sub>.', dont: 'Nepleť s Diracovou deltou δ(x − x′) pre spojité bázy.' },

  // ---------- Level 6: Rabiho rezonátor ----------
  { id: 'rabi', level: 6, type: 'osobnost', sym: '👤', name: 'Isidor Isaac Rabi (1898–1988)', text: 'Magnetická rezonancia v molekulových zväzkoch (1938) → NMR, MRI, atómové hodiny. Nobelova cena 1944. Spoluzakladateľ CERN.' },
  { id: 'zeeman', level: 6, type: 'osobnost', sym: '👤', name: 'Pieter Zeeman (1865–1943)', text: 'Rozštiepenie spektrálnych čiar v magnetickom poli. Spin ½ v poli B₀ má dve Zeemanove hladiny = qubit v NMR.' },
  { id: 'B0', level: 6, type: 'symbol', sym: 'B₀', name: 'statické magnetické pole', text: 'Vytvorí dve energetické hladiny; okolo osi z spin precesuje. Musí byť stabilné a homogénne.' },
  { id: 'OmegaR', level: 6, type: 'symbol', sym: 'Ω<sub>R</sub>', name: 'Rabiho frekvencia', text: 'Rýchlosť rotácie pod RF impulzom. Ω<sub>R</sub>t = plocha impulzu: π = preklopenie, π/2 = rovník.', dont: 'Nepleť s rezonančnou (Larmorovou) frekvenciou ω.' },
  { id: 'precess', level: 6, type: 'pojem', sym: '↻', name: 'precesia', text: 'Kvantovo: vývoj relatívnej fázy a stredných hodnôt. P(0), P(1) sa nemenia.', dont: 'Nie je to otáčanie osi mechanického gyroskopu.' },
  { id: 'rabiosc', level: 6, type: 'pojem', sym: '〰', name: 'Rabiho oscilácie', text: 'Periodická zmena AMPLITÚD a pravdepodobností pod rezonančným poľom.', dont: 'Elektrón sa mechanicky nepresúva medzi dvoma polohami.' },
  { id: 'rotframe', level: 6, type: 'pojem', sym: '🎠', name: 'rotujúci rámec', text: 'Súradnice, ktoré sa točia s rezonančnou frekvenciou — rýchla precesia sa „zastaví“.', dont: 'Je to matematický trik, nie otáčanie laboratória.' },
  { id: 'T2', level: 6, type: 'symbol', sym: 'T₁, T₂', name: 'relaxačné časy', text: 'T₂: strata fázovej koherencie (dephasing). T₁: návrat populácií k tepelnému stavu (amplitúdový šum).' },
  { id: 'ensemble', level: 6, type: 'pojem', sym: '🧪', name: 'ansámblové meranie (NMR, SpinQ)', text: 'Meriame signál obrovského množstva molekúl (priečna magnetizácia) → stredná hodnota, nie jednotlivé výsledky.' },

  // ---------- Level 7: Bellov most ----------
  { id: 'bell', level: 7, type: 'osobnost', sym: '👤', name: 'John Stewart Bell (1928–1990)', text: 'CERN. 1964: žiadna lokálna teória s predexistujúcimi hodnotami nereprodukuje kvantové korelácie. Nobelova cena 2022 za experimenty (Aspect, Clauser, Zeilinger).' },
  { id: 'einstein', level: 7, type: 'osobnost', sym: '👤', name: 'Albert Einstein (1879–1955)', text: 'Svetelné kvantá (1905), Nobelova cena 1921. EPR (1935): QM je podľa neho neúplná — „strašidelné pôsobenie na diaľku“.' },
  { id: 'cnot', level: 7, type: 'symbol', sym: 'CNOT', name: 'riadené NOT', text: 'Ak je riadiaci qubit |1⟩, preklopí cieľový. Spolu s H vytvára previazanosť. V NMR cez J-väzbu.' },
  { id: 'phiplus', level: 7, type: 'symbol', sym: '|Φ⁺⟩', name: 'Bellov stav', text: '(|00⟩ + |11⟩)/√2 — maximálne previazaný. Nedá sa zapísať ako súčin.', dont: 'Previazaný qubit NEMÁ vlastnú šípku na Blochovej sfére (je v strede).' },
  { id: 'entangle', level: 7, type: 'pojem', sym: '🔗', name: 'previazanosť (entanglement)', text: 'Korelácie silnejšie než klasické. Pojem zaviedol Schrödinger 1935.', dont: 'Neumožňuje nadsvetelnú komunikáciu. Nie je to „neviditeľné lano“.' },
  { id: 'chsh', level: 7, type: 'pojem', sym: '75 %', name: 'Bellova (CHSH) nerovnosť', text: 'Lokálna stratégia vyhrá CHSH hru najviac v 75 %. Previazané qubity ~85 %.', do: 'Čítaj: nemožno zároveň zachovať lokálnosť a predexistujúce hodnoty.' },
  { id: 'nosignal', level: 7, type: 'pojem', sym: '📵', name: 'nemožnosť signalizácie', text: 'Bob vidí 50/50 nech Alice robí čokoľvek. Korelácie uvidí až po porovnaní výsledkov klasickým kanálom.' },

  // ---------- Level 8: Sieň výkladov ----------
  { id: 'bohr', level: 8, type: 'osobnost', sym: '👤', name: 'Niels Bohr (1885–1962)', text: 'Model atómu, Nobelova cena 1922, komplementarita (1927). Jav nemožno opísať bez experimentálnych podmienok.', dont: 'Komplementarita nie je relativizmus.' },
  { id: 'kant', level: 8, type: 'osobnost', sym: '👤', name: 'Immanuel Kant (1724–1804)', text: '„Podmienky možnosti skúsenosti sú podmienkami možnosti predmetov skúsenosti.“ Kvantový stav = podmienky možnosti výsledku.' },
  { id: 'wittg', level: 8, type: 'osobnost', sym: '👤', name: 'Ludwig Wittgenstein (1889–1951)', text: '„Hranice môjho jazyka znamenajú hranice môjho sveta.“ „Význam slova je jeho použitie.“ Pôvodne inžinier.' },
  { id: 'bohm', level: 8, type: 'osobnost', sym: '👤', name: 'David Bohm (1917–1992)', text: 'Pilotná vlna a skryté premenné (1952): deterministická, ale NELOKÁLNA teória.' },
  { id: 'stodola', level: 8, type: 'osobnost', sym: '👤', name: 'Aurel Stodola (1859–1942)', text: 'Liptovský Mikuláš → ETH Zürich, parné turbíny. Inžiniersky realizmus: teória ako konštrukčný rámec.' },
  { id: 'heis', level: 8, type: 'osobnost', sym: '👤', name: 'Werner Heisenberg (1901–1976)', text: 'Maticová mechanika (1925), princíp neurčitosti (1927). „Pozorujeme prírodu vystavenú nášmu spôsobu kladenia otázok.“' },
  { id: 'noether', level: 8, type: 'osobnost', sym: '👤', name: 'Emmy Noether (1882–1935)', text: 'Symetria ↔ zákon zachovania. Pred meraním: symetria (možnosť); po meraní: fakt.' },
  { id: 'collapse', level: 8, type: 'pojem', sym: '⚡', name: 'kolaps ako inžinierska operácia', text: 'Readout: zosilnenie → prepojenie s makrosvetom → zápis do klasického registra. Ireverzibilný.', dont: 'Nie je to magický zásah vedomia.' },
  { id: 'onto', level: 8, type: 'pojem', sym: '❓❓❓', name: 'ontológia / epistemológia / fenomenológia', text: 'Čo existuje? / Čo o tom môžeme vedieť? / Ako sa nám jav ukazuje?' },
  { id: 'four', level: 8, type: 'pojem', sym: '4️⃣', name: 'štyri otázky ku každému pojmu', text: 'Aký systém? Aká rovnica a predpoklady? Aký experiment? Čo z opisu NEvyplýva?' },
  // ---------- Level 9: Pauliho rotačná dielňa (prednáška 4) ----------
  { id: 'pauli', level: 9, type: 'osobnost', sym: '👤', name: 'Wolfgang Pauli (1900–1958)', text: 'Princíp vylúčenia (1925), Pauliho matice σ<sub>x</sub>, σ<sub>y</sub>, σ<sub>z</sub> pre spin ½ (1927), predpoveď neutrína. Nobelova cena 1945. Povestne prísny kritik: „To nie je ani nesprávne.“' },
  { id: 'notphysball', level: 9, type: 'pojem', sym: '🌐≠🏀', name: 'Blochova sféra nie je fyzická guľa', text: 'Je to geometrický obraz priestoru stavov. Šípka predstavuje kvantový stav, nie smer malého rotujúceho objektu.', dont: 'Opačné body nie sú „opačné šípky“ — sú to ORTOGONÁLNE stavy. Globálna fáza na sfére vôbec nie je.' },
  { id: 'sigmavec', level: 9, type: 'symbol', sym: 'σ = (σ<sub>x</sub>, σ<sub>y</sub>, σ<sub>z</sub>)', name: 'Pauliho vektor', text: 'Trojica Pauliho matíc. n·σ je spinová observabla v smere n; ρ = ½(I + r·σ).', dont: 'σ nie je vektor v laboratóriu — je to trojica matíc 2 × 2.' },
  { id: 'rotgate', level: 9, type: 'symbol', sym: 'R<sub>n</sub>(ϑ)', name: 'rotácia qubitu', text: 'R<sub>n</sub>(ϑ) = exp(−iϑ n·σ/2): otočenie Blochovho vektora o uhol ϑ okolo osi n. X ∼ R<sub>x</sub>(π), Y ∼ R<sub>y</sub>(π), Z ∼ R<sub>z</sub>(π).', do: 'Hradlo = pravidlo pohybu stavu: |ψ′⟩ = U|ψ⟩ ⇔ r′ = Rr.', dont: 'R<sub>y</sub>(π/2) ≠ H ako operátory, hoci z |0⟩ obe dajú |+⟩.' },
  { id: 'phitomo', level: 9, type: 'pojem', sym: 'φ = atan2(r<sub>y</sub>, r<sub>x</sub>)', name: 'φ zo štatistiky meraní', text: 'Jedno meranie spinu dá vždy len ±ħ/2. Uhol φ sa zistí zo stredných hodnôt ⟨S<sub>x</sub>⟩ a ⟨S<sub>y</sub>⟩ — základ tomografie qubitu.', dont: '⟨S<sub>z</sub>⟩ = (ħ/2) cos θ nie je výsledok jedného merania — je to priemer mnohých.' },
  { id: 'larmor', level: 9, type: 'symbol', sym: 'ω₀ = γB₀', name: 'Zeemanov Hamiltonián a precesia', text: 'H<sub>Z</sub> = −μ·B = −(γħ/2) σ·B. Schrödingerova evolúcia ⇒ dr/dt = γ r × B: Blochov vektor rotuje okolo poľa s Larmorovou frekvenciou ω₀ = γB₀.', dont: 'Unitárna evolúcia nemení |r| — dekoherencia áno (pohyb dovnútra gule).' },

  // ---------- Level 10: Von Neumannova čistiareň (prednáška 5) ----------
  { id: 'neumann', level: 10, type: 'osobnost', sym: '👤', name: 'John von Neumann (1903–1957)', text: 'Matica hustoty (1927), Matematické základy kvantovej mechaniky (1932): Hilbertov priestor, projektívne meranie, entropia −Tr ρ ln ρ. Aj architektúra počítačov a teória hier.' },
  { id: 'purity', level: 10, type: 'symbol', sym: 'Tr ρ²', name: 'čistota stavu', text: 'Pre qubit Tr ρ² = (1 + |r|²)/2: 1 = čistý, ½ = maximálne zmiešaný. Unitárne ρ′ = UρU† ju nemení.', dont: 'Žiadna kombinácia hradiel nedostane stav s |r| = 0,4 na povrch.' },
  { id: 'purify', level: 10, type: 'pojem', sym: '❄📏', name: 'purifikácia', text: 'Čistejší stav vznikne len neunitárne: meraním so známym výsledkom alebo chladením (relaxácia |1⟩ → |0⟩). Entropia/informácia odchádza do okolia.', dont: 'Meranie so zabudnutým výsledkom stav nevyčistí — zmes zostane.' },
  { id: 'pps', level: 10, type: 'symbol', sym: 'ρ<sub>pps</sub>', name: 'pseudo-čistý stav (NMR)', text: 'ρ<sub>pps</sub> = (1 − ε) I/4 + ε|00⟩⟨00|, ε ≪ 1. Unitárne U nemení I, takže odchýlka sa transformuje ako čistý stav. Pre qubit r = εn.', dont: 'Nie je to čistý stav — Blochov vektor je blízko stredu, len smeruje správne.' },
  { id: 'observable', level: 10, type: 'symbol', sym: 'A = A†', name: 'observábla', text: 'Merateľnej veličine zodpovedá samoadjungovaný operátor; vlastné čísla = možné výsledky. ⟨A⟩ = Tr(ρA), ⟨n·σ⟩ = r·n, r = (⟨σ<sub>x</sub>⟩, ⟨σ<sub>y</sub>⟩, ⟨σ<sub>z</sub>⟩).', dont: 'Stredná hodnota nemusí byť vlastným číslom (⟨σ<sub>z</sub>⟩ = 0,3 je v poriadku).' },
  { id: 'timeevo', level: 10, type: 'symbol', sym: 'e<sup>−iHt/ħ</sup>', name: 'operátor časového vývoja', text: 'U(t) = exp(−iHt/ħ) je unitárny (U†U = I). Energetický vlastný stav získa len fázu e<sup>−iE<sub>n</sub>t/ħ</sup>; |a<sub>n</sub>|² sa nemenia, menia sa relatívne fázy Δφ = −(E₂ − E₁)t/ħ.', dont: 'Pri časovo závislom H(t) nestačí e<sup>−iHt/ħ</sup> — treba časovo usporiadaný exponenciál.' },

  // ---------- Level 11: Bornova meracia sieň (prednáška 5) ----------
  { id: 'born', level: 11, type: 'osobnost', sym: '👤', name: 'Max Born (1882–1970)', text: 'Pravdepodobnostný výklad vlnovej funkcie (1926): P = |ψ|². S Heisenbergom a Jordanom maticová mechanika. Nobelova cena 1954.' },
  { id: 'projmeas', level: 11, type: 'symbol', sym: 'P<sub>k</sub> = |k⟩⟨k|', name: 'projektívne meranie', text: 'p(k) = Tr(ρP<sub>k</sub>); po výsledku k: ρ → P<sub>k</sub>ρP<sub>k</sub>/Tr(ρP<sub>k</sub>). Všeobecne POVM: E<sub>k</sub> ≥ 0, ΣE<sub>k</sub> = I.', dont: 'Meranie nie je len „čítanie“ — mení ďalšie možnosti systému.' },
  { id: 'interfmeas', level: 11, type: 'pojem', sym: 'φ → ∿ → P', name: 'fáza → interferencia → pravdepodobnosť', text: '|+⟩ a |−⟩ majú v Z-báze rovnaké P(0) = P(1) = ½. Až hradlo H premení relatívnu fázu na rozdielne pravdepodobnosti: H|+⟩ = |0⟩, H|−⟩ = |1⟩.' },
  { id: 'midmeas', level: 11, type: 'pojem', sym: 'H·M·H', name: 'meranie uprostred obvodu', text: 'Bez merania H·H = I (vždy 0). S meraním medzi hradlami sa vetvy už nezložia — výsledok je 50 : 50. Miesto merania je súčasťou algoritmu.' },
  { id: 'feedbackc', level: 11, type: 'pojem', sym: '📏→🤔→▶', name: 'klasická spätná väzba', text: 'Zmeraj → rozhodni → pokračuj: výsledok merania určí ďalšie hradlo (aktívny reset, korekcia chýb cez syndrómy).', dont: 'Meranie nemusí byť poslednou operáciou výpočtu.' },
  { id: 'decoread', level: 11, type: 'pojem', sym: '🌫 ≠ 📏', name: 'dekoherencia ≠ readout', text: 'Dekoherencia potláča mimodiagonálu ρ (interferenciu), ale sama nevytvorí konkrétny klasický záznam. Readout je fyzický reťazec: interakcia → zosilnenie → signál → register.' },
  { id: 'tomography', level: 11, type: 'pojem', sym: 'ρ ← {ZZ, XX, …}', name: 'tomografia stavu', text: 'Jedna báza vidí len diagonálu ρ. Bellov stav a zmes ½|00⟩⟨00| + ½|11⟩⟨11| dajú v ZZ to isté; líšia sa mimodiagonálou ρ<sub>00,11</sub> = ½ — viditeľnou až v inej báze (XX).', dont: 'Samotná korelácia A = B nedokazuje previazanosť.' },
  // ---------- Level 12: NMR dielňa (praktické NMR) ----------
  { id: 'purcell', level: 12, type: 'osobnost', sym: '👤', name: 'Edward Mills Purcell (1912–1997)', text: 'V roku 1946 nezávisle od Felixa Blocha zmeral jadrovú magnetickú rezonanciu v pevnej látke (parafín). Nobelova cena 1952 spolu s Blochom.' },
  { id: 'nmrsetup', level: 12, type: 'pojem', sym: '🧲⟂📻', name: 'zostava NMR spektrometra', text: 'Magnet so stálym poľom B₀ (os z), vzorka a priečna RF cievka (os x): impulzmi prúdu na frekvencii ν<sub>RF</sub> vytvára pole B₁ ⟂ B₀ a potom tá istá cievka zachytí indukovaný signál.', dont: 'Cievka nie je napájaná stálym prúdom — dostáva krátke RF impulzy; stály je magnet B₀.' },
  { id: 'larmortune', level: 12, type: 'symbol', sym: 'ν₀ = γB₀/2π', name: 'rezonancia vysielača', text: 'Larmorovu frekvenciu určuje pole B₀ a jadro (protón: 42,577 MHz/T). Vysielač sa nastaví na ν<sub>RF</sub> = ν₀; rozladenie Δν = ν₀ − ν<sub>RF</sub> je precesia v rotujúcom rámci.', dont: 'Larmorovu frekvenciu „neladíš“ gombíkom — meníš B₀ alebo ladíš vysielač.' },
  { id: 'flipangle', level: 12, type: 'symbol', sym: 'θ = γB₁τ', name: 'uhol preklopenia', text: 'Uhol, o ktorý RF impulz otočí magnetizáciu: závisí od amplitúdy B₁ (prúdu v cievke) a dĺžky τ. Fáza impulzu určuje os v priečnej rovine (x, y, …).' },
  { id: 'fid', level: 12, type: 'pojem', sym: 'FID', name: 'voľný indukčný rozpad', text: 'Po 90° impulze priečna magnetizácia precesuje okolo B₀ a indukuje v cievke striedavé napätie, ktoré doznieva s T₂*. 180° impulz z rovnováhy signál nedá (M<sub>⊥</sub> = 0).' },
  { id: 'nutation', level: 12, type: 'pojem', sym: '∿ 0', name: 'kalibrácia impulzu (nutácia)', text: 'Amplitúda FID ∝ sin(γB₁τ). Nula signálu pri preklopení nadol = skutočný 180° impulz; 90° je polovica. Tak sa opraví neznáma chyba B₁.' },
  { id: 'spinecho', level: 12, type: 'pojem', sym: '90° – τ – 180° – τ', name: 'spinové echo (Hahn 1950)', text: '180° impulz v čase τ zrkadlí fázy izochromát rozbehnutých nehomogenitou B₀; v čase 2τ sa znova zložia. Echo obnoví signál až po skutočné T₂.', dont: 'Echo nezvráti skutočnú dekoherenciu T₂ — len statickú nehomogenitu.' },
  { id: 'shim', level: 12, type: 'pojem', sym: '🔧 B₀', name: 'shim', text: 'Prídavné korekčné cievky (shimy) vyrovnávajú nehomogenitu poľa B₀ a predlžujú T₂*. Úplne dokonalé pole sa nedosiahne.' },

  // ---------- Level 14: Reťaz superpozícií (prednáška 7) ----------
  { id: 'manin', level: 14, type: 'osobnost', sym: '👤', name: 'Jurij Manin (1937–2023)', text: 'Ruský matematik; v knihe z roku 1980 ako jeden z prvých navrhol, že kvantové systémy by mohli počítať nad exponenciálne veľkým stavovým priestorom.' },
  { id: 'tensorn', level: 14, type: 'symbol', sym: '⊗ⁿ', name: 'register z tenzorových súčinov', text: 'n qubitov skladáme tenzorovým súčinom: |q₁⟩⊗…⊗|qₙ⟩. Bázové stavy registra sú |00…0⟩ … |11…1⟩.', do: 'Lokálne hradlo na jednom qubite pôsobí ako U⊗I⊗… na celý register.', dont: 'Previazaný stav sa vo všeobecnosti NEDÁ zapísať ako jeden tenzorový súčin.' },
  { id: 'dimgrow', level: 14, type: 'symbol', sym: '2ⁿ', name: 'exponenciálny rast stavu', text: 'n qubitov má 2ⁿ komplexných amplitúd. 300 qubitov má viac amplitúd než je atómov vo vesmíre — zdroj kvantovej sily.', dont: 'Neznamená to 2ⁿ paralelných svetov, ktoré by sa dali naraz prečítať — meranie dá len n bitov.' },
  { id: 'ghz', level: 14, type: 'pojem', sym: 'GHZ', name: 'GHZ reťaz', text: '(|00…0⟩ + |11…1⟩)/√2: maximálne previazaná reťaz. Jediné meranie jedného qubitu určí všetky ostatné.', dont: 'Nie je to zmes — kým nezmeriaš, žiadny qubit nemá určenú hodnotu.' },

  // ---------- Level 15: Fourierova veža (prednáška 7) ----------
  { id: 'fourierp', level: 15, type: 'osobnost', sym: '👤', name: 'Joseph Fourier (1768–1830)', text: 'Francúzsky matematik a fyzik; ukázal, že ľubovoľný signál sa dá rozložiť na súčet harmonických vĺn. Kvantová verzia jeho transformácie je jadrom Shorovho algoritmu.' },
  { id: 'dft', level: 15, type: 'symbol', sym: 'DFT', name: 'diskrétna Fourierova transformácia', text: 'Prevedie postupnosť vzoriek na jej frekvencie: X<sub>k</sub> = Σ<sub>j</sub> x<sub>j</sub> e<sup>−2πijk/N</sup>. Odhalí skrytú periodicitu signálu.' },
  { id: 'qft', level: 15, type: 'symbol', sym: 'QFT', name: 'kvantová Fourierova transformácia', text: 'DFT vykonaná na amplitúdach registra pomocou hradiel H a riadených fáz. Na n qubitoch stačí ~n² hradiel namiesto N log N operácií.', dont: 'QFT sama nič nemeria — výsledok (periódu) odhalí až meranie po inverznej QFT.' },
  { id: 'periodfind', level: 15, type: 'pojem', sym: 'r: f(x+r)=f(x)', name: 'hľadanie periódy', text: 'Mnohé ťažké úlohy (napr. faktorizácia) sa dajú previesť na nájdenie periódy funkcie. QFT premení periódu na ostrý vrchol v báze frekvencií.' },

  // ---------- Level 16: Sieň algoritmov (prednáška 7) ----------
  { id: 'deutschp', level: 16, type: 'osobnost', sym: '👤', name: 'David Deutsch (* 1953)', text: 'Britský fyzik; v roku 1985 opísal univerzálny kvantový počítač a prvý algoritmus s kvantovou výhodou (Deutschov problém).' },
  { id: 'oracle', level: 16, type: 'pojem', sym: 'U<sub>f</sub>', name: 'orákulum a fázový spätný ráz', text: 'Funkciu f skryjeme do unitárneho U<sub>f</sub>. „Fázový spätný ráz“ zapíše odpoveď do fázy amplitúdy — Deutsch aj Bernstein–Vazirani ju prečítajú interferenciou na jediný dotaz.', dont: 'Kvantová výhoda nie je v „skúšaní všetkých vstupov naraz“, ale v interferencii fáz.' },
  { id: 'grover', level: 16, type: 'symbol', sym: '~√N', name: 'Groverovo hľadanie', text: 'Hľadanie v neutriedenej databáze N položiek: zosilňovaním amplitúdy správnej odpovede stačí ~√N krokov namiesto N. Kvadratické zrýchlenie.', dont: 'Nie je to exponenciálne zrýchlenie — a priveľa iterácií amplitúdu zase zníži.' },
  { id: 'shoralg', level: 16, type: 'symbol', sym: 'N = p·q', name: 'Shorov algoritmus', text: 'Rozklad veľkého čísla na prvočísla prevedie na hľadanie periódy a vyrieši ju QFT — exponenciálne rýchlejšie než známe klasické metódy. Ohrozuje šifru RSA.', dont: 'Nelúšti „všetky šifry“ — len tie postavené na faktorizácii a diskrétnom logaritme.' },

  // ---------- Level 17: Štít korekcie chýb (prednáška 7) ----------
  { id: 'shorp', level: 17, type: 'osobnost', sym: '👤', name: 'Peter Shor (* 1959)', text: 'Americký matematik; okrem faktorizačného algoritmu (1994) navrhol aj prvý kód na kvantovú korekciu chýb (1995) — 9-qubitový kód.' },
  { id: 'bitflip', level: 17, type: 'pojem', sym: '|0⟩→|000⟩', name: 'bit-flip kód', text: 'Jeden logický qubit zakódujeme do troch: |0⟩→|000⟩, |1⟩→|111⟩. Jedno preklopenie bitu odhalí a opraví hlasovanie väčšiny.', dont: 'Qubit sa nedá kopírovať (no-cloning) — kóduje sa previazaním, nie kopírovaním stavu.' },
  { id: 'phaseflipc', level: 17, type: 'pojem', sym: '|+⟩→|+++⟩', name: 'phase-flip kód', text: 'Chyba fázy (Z) je chyba bitu v báze |+⟩, |−⟩. Hadamardmi prejdeme do tejto bázy a použijeme ten istý trik. Shorov 9-qubitový kód skombinuje oba.' },
  { id: 'syndrome', level: 17, type: 'pojem', sym: 'ZZ, XX', name: 'syndrómové meranie', text: 'Zmeriame parity (napr. Z₁Z₂) pomocných qubitov: zistíme, ČI a KDE nastala chyba, bez toho, aby sme zmerali — a tým zničili — uloženú informáciu.', dont: 'Priame meranie dátového qubitu by ho skolabovalo; preto meriame len parity.' },

  // ---------- Level 18: Chemická kúria NMR (prednáška 7) ----------
  { id: 'pauling', level: 18, type: 'osobnost', sym: '👤', name: 'Linus Pauling (1901–1994)', text: 'Americký chemik; objasnil povahu chemickej väzby (Nobelova cena 1954). Práve kovalentné väzby sprostredkúvajú J-väzbu medzi jadrami v molekulovom NMR počítači.' },
  { id: 'cshift', level: 18, type: 'symbol', sym: 'δ (ppm)', name: 'chemický posun', text: 'Elektróny okolo jadra čiastočne tienia pole B₀, takže každé jadro v molekule rezonuje na mierne inej frekvencii. Vďaka tomu je každé samostatne adresovateľným qubitom.', dont: 'Rôzne frekvencie nevznikajú z rôznych jadier toho istého druhu „samých osebe“ — robí to ich chemické okolie.' },
  { id: 'jcoupling', level: 18, type: 'symbol', sym: 'J', name: 'J-väzba (spin-spinová)', text: 'Spiny dvoch jadier sa „cítia“ cez zdieľané elektróny kovalentnej väzby. Toto prepojenie je prirodzené dvojqubitové hradlo (napr. riadené fázové).', dont: 'J-väzba ide cez väzby molekuly, nie priamo priestorom (to je dipólová väzba).' },
  { id: 'molreg', level: 18, type: 'pojem', sym: '🧪→🧮', name: 'molekula ako register', text: 'Malá molekula (napr. chloroform, alanín) sa stáva registrom qubitov: jadrá sú qubity, chemický posun ich adresuje, J-väzba ich prepája. Tak bežali prvé Shorove demonštrácie.', dont: 'Pracuje sa s miliardami molekúl naraz (pseudo-čistý stav), nie s jednou.' },

  // ---------- Level 19: Majoranov maják (prednáška 7) ----------
  { id: 'majoranap', level: 19, type: 'osobnost', sym: '👤', name: 'Ettore Majorana (1906–?)', text: 'Taliansky fyzik; v roku 1937 opísal časticu, ktorá je vlastnou antičasticou. V roku 1938 záhadne zmizol. Jeho „fermióny“ sú dnes nádejou topologických qubitov.' },
  { id: 'zeromode', level: 19, type: 'pojem', sym: 'γ', name: 'Majoranov nulový mód', text: 'Elektrón sa v špeciálnom nanodrôte „rozdelí“ na dve polovice (nulové módy) na jeho koncoch. Jeden qubit je uložený nelokálne v oboch naraz.', dont: 'Majoranov mód nie je bežná častica, ktorú by sa dalo lokálne „chytiť“ a zmerať.' },
  { id: 'topqubit', level: 19, type: 'pojem', sym: '🛡', name: 'topologický qubit', text: 'Keďže informácia je uložená nelokálne, lokálny šum ju nedokáže ľahko pokaziť — ochrana pred chybami je „zabudovaná“ v topológii.', dont: 'Ochrana nie je dokonalá a takéto qubity sa zatiaľ len experimentálne overujú.' },
  { id: 'braiding', level: 19, type: 'symbol', sym: '⤭', name: 'pletenie (braiding)', text: 'Hradlá sa robia zámenou polôh Majoran — ich „pletením“. Výsledok závisí od poradia (neabelovské anyóny), preto vznikne robustná operácia.', dont: 'Pri bežných časticiach (fermiónoch, bozónoch) na poradí zámeny nezáleží — tu áno.' },
  // ---------- Level 20: Dielňa previazanosti (prednáška 7) ----------
  { id: 'schmidtp', level: 20, type: 'osobnost', sym: "👤", name: "Erhard Schmidt (1876–1959)", text: "Nemecký matematik, žiak Hilberta. Jeho rozklad (1907) — dnes Schmidtov rozklad — ukazuje, že každý čistý stav dvoch systémov má tvar Σ√λᵢ|uᵢ⟩|vᵢ⟩ a koeficienty λᵢ merajú previazanosť." },
  { id: 'prodstate', level: 20, type: 'pojem', sym: "⊗", name: "separovateľný (produktový) stav", text: "Stav |ψ⟩ = |a⟩ ⊗ |b⟩ — každý podsystém má vlastný čistý stav. Pre dva qubity platí: (α|0⟩+β|1⟩)(γ|0⟩+δ|1⟩) ⇔ koeficienty spĺňajú ad = bc.", dont: "Superpozícia ešte neznamená previazanosť: |+⟩|+⟩ je produktový stav." },
  { id: 'ptrace', level: 20, type: 'symbol', sym: "Tr<sub>B</sub>", name: "čiastočná stopa", text: "ρ<sub>A</sub> = Tr<sub>B</sub> |ψ⟩⟨ψ| — opis podsystému A, keď o B nevieme nič. Pre previazaný čistý stav je ρ<sub>A</sub> zmiešaný; pre Bellov stav ρ<sub>A</sub> = I/2.", dont: "Zmiešaný ρ<sub>A</sub> tu nie je „neznalosť pripravovateľa“ — vzniká len z previazanosti s B." },
  { id: 'schmidt', level: 20, type: 'symbol', sym: "√λᵢ", name: "Schmidtov rozklad", text: "|ψ⟩ = Σᵢ √λᵢ |uᵢ⟩|vᵢ⟩, λᵢ ≥ 0, Σλᵢ = 1 (singulárne hodnoty matice koeficientov). Počet nenulových λᵢ je Schmidtovo číslo: 1 = produktový stav, viac = previazaný.", dont: "Báza |uᵢ⟩, |vᵢ⟩ závisí od stavu — nie je to vždy výpočtová báza." },
  { id: 'entent', level: 20, type: 'symbol', sym: "E = S(ρ<sub>A</sub>)", name: "entropia previazanosti", text: "E = S(ρ<sub>A</sub>) = −Σ λᵢ log₂ λᵢ. Pre dva qubity od 0 (produktový stav) po 1 ebit (Bellov stav, λ₁ = λ₂ = ½).", dont: "E sa nedá zvýšiť lokálnymi operáciami a klasickou komunikáciou (LOCC)." },
  { id: 'teleport', level: 20, type: 'pojem', sym: "📤", name: "kvantová teleportácia", text: "Alica a Bob zdieľajú Bellov pár. Alica zmeria svoj neznámy qubit spolu so svojou polovicou v Bellovej báze a pošle 2 klasické bity; Bob podľa nich použije I, X, Z alebo XZ a dostane pôvodný stav.", dont: "Neprenáša sa hmota ani informácia rýchlejšie ako svetlo — bez 2 klasických bitov má Bob len I/2. Originál sa zničí (no-cloning)." },
  { id: 'superdense', level: 20, type: 'pojem', sym: "2 bity", name: "superhusté kódovanie", text: "Opak teleportácie: Alica pošle 1 qubit (svoju polovicu Bellovho páru) po I, X, Z alebo XZ a Bob z Bellovho merania prečíta 2 klasické bity.", dont: "Bez predtým zdieľanej previazanosti 1 qubit prenesie najviac 1 bit (Holevova hranica)." },

  // ---------- Level 21: Bellov stav na SpinQ (prednáška 7) ----------
  { id: 'chuangp', level: 21, type: 'osobnost', sym: "👤", name: "Isaac Chuang (1968)", text: "Americký fyzik (MIT), spoluautor učebnice Nielsen & Chuang. V roku 2001 jeho tím na 7-qubitovom NMR počítači faktorizoval 15 = 3 × 5 Shorovým algoritmom." },
  { id: 'bellfour', level: 21, type: 'symbol', sym: "Φ± Ψ±", name: "štyri Bellove stavy", text: "|Φ±⟩ = (|00⟩ ± |11⟩)/√2, |Ψ±⟩ = (|01⟩ ± |10⟩)/√2. Tvoria ortonormálnu bázu dvoch qubitov; vzniknú z |00⟩ cez H na prvom qubite a CNOT, prípadne s X/Z." },
  { id: 'paulicorr', level: 21, type: 'symbol', sym: "⟨σᵢσⱼ⟩", name: "Pauliho korelácie", text: "Dvojqubitový stav sa dá zapísať ako ρ = ¼ Σ cᵢⱼ σᵢ⊗σⱼ. Pre |Φ+⟩ sú ⟨XX⟩ = 1, ⟨YY⟩ = −1, ⟨ZZ⟩ = 1 a lokálne ⟨X⟩ = ⟨Y⟩ = ⟨Z⟩ = 0.", dont: "Nulové lokálne stredné hodnoty neznamenajú „žiadnu informáciu“ — tá je celá v koreláciách." },
  { id: 'jgate', level: 21, type: 'pojem', sym: "e<sup>−iπJτ ZZ/2</sup>", name: "hradlo z J-väzby", text: "Voľný vývoj s J-väzbou H = (πJ/2) Z⊗Z počas τ = 1/(2J) (pri J ≈ 126 Hz ≈ 4 ms) spolu s jednoqubitovými pulzmi dá CNOT / riadenú fázu." },
  { id: 'ppseps', level: 21, type: 'symbol', sym: "ε ~ 10⁻⁵", name: "polarizácia ε", text: "Pri izbovej teplote je ρ = (1 − ε) I/4 + ε |ψ⟩⟨ψ| s ε ~ 10⁻⁵. Identita nedáva signál, takže meriame len odchýlku ε|ψ⟩⟨ψ|.", dont: "Taký stav je takmer úplne zmiešaný a v skutočnosti nie je previazaný — NMR „Bellov stav“ je pseudo-čistý." },
  { id: 'tomo15', level: 21, type: 'symbol', sym: "4² − 1 = 15", name: "15 parametrov tomografie", text: "Matica hustoty dvoch qubitov (4×4, hermitovská, stopa 1) má 15 reálnych parametrov — treba zmerať všetky korelácie σᵢ⊗σⱼ okrem I⊗I. Fázu off-diagonálnych prvkov vidno cez oneskorenie a rotácie pred meraním." },
  { id: 'tripsing', level: 21, type: 'pojem', sym: "S = 1 / S = 0", name: "triplet a singlet", text: "Dva spiny ½ sa skladajú na triplet (S = 1: |↑↑⟩, (|↑↓⟩ + |↓↑⟩)/√2, |↓↓⟩) a singlet (S = 0: (|↑↓⟩ − |↓↑⟩)/√2 = |Ψ−⟩). Singlet je rotačne invariantný." },

  // ---------- Level 22: Orákulum fáz (prednáška 7) ----------
  { id: 'jozsap', level: 22, type: 'osobnost', sym: "👤", name: "Richard Jozsa (1953)", text: "Britský matematik a fyzik; s Davidom Deutschom navrhol v roku 1992 Deutschov–Jozsov algoritmus, jeden z prvých dôkazov kvantového zrýchlenia. Je aj spoluautorom protokolu teleportácie (1993)." },
  { id: 'plusminus', level: 22, type: 'symbol', sym: "|±⟩", name: "stavy |+⟩ a |−⟩", text: "|±⟩ = (|0⟩ ± |1⟩)/√2 = H|0⟩, H|1⟩. Líšia sa len relatívnou fázou; v báze Z dávajú 50 : 50, v báze X sú rozlíšiteľné s istotou." },
  { id: 'phaseor', level: 22, type: 'symbol', sym: "U<sub>f</sub>|x⟩ = (−1)<sup>f(x)</sup>|x⟩", name: "fázové orákulum", text: "Orákulum, ktoré hodnotu f(x) nezapíše do bitu, ale do znamienka amplitúdy. Vznikne z U<sub>f</sub>|x⟩|y⟩ = |x⟩|y ⊕ f(x)⟩ s pomocným qubitom v |−⟩.", dont: "Samotné znamienko sa meraním v báze Z nedá zistiť — treba interferenciu (H po orákule)." },
  { id: 'turingor', level: 22, type: 'pojem', sym: "🗝", name: "Turingovo orákulum", text: "Turing (1939) zaviedol „orákulum“ ako čiernu skrinku, ktorá odpovie na otázku v jednom kroku. Zložitosť dotazov počíta len počet volaní, nie to, čo je vnútri." },
  { id: 'kickback', level: 22, type: 'pojem', sym: "↩", name: "fázový spätný ráz (kickback)", text: "Ak je cieľ v |−⟩, CNOT-ové orákulum ho nezmení, ale fáza (−1)<sup>f(x)</sup> sa „odrazí“ na riadiaci register: |x⟩|−⟩ → (−1)<sup>f(x)</sup>|x⟩|−⟩.", dont: "Riadiaci qubit nie je „len čítaný“ — kvantovo sa mení aj on." },
  { id: 'deutschalg', level: 22, type: 'pojem', sym: "f(0) ⊕ f(1)", name: "Deutschov algoritmus", text: "Pre f: {0,1} → {0,1} zistí, či je konštantná alebo vyvážená, jediným volaním: H, orákulum, H a meranie — 0 = konštantná, 1 = vyvážená. Klasicky treba 2 volania.", dont: "Nezistíme f(0) ani f(1) samostatne — len ich XOR (globálnu vlastnosť)." },

  // ---------- Level 23: Walshova–Hadamardova dielňa (prednáška 7) ----------
  { id: 'bvp', level: 23, type: 'osobnost', sym: "👤", name: "Ethan Bernstein & Umesh Vazirani", text: "Americkí informatici; v roku 1993 ukázali problém skrytého reťazca s ⋅ x, ktorý kvantový počítač vyrieši jedným dotazom (klasicky n dotazov), a položili základy kvantovej teórie zložitosti (trieda BQP)." },
  { id: 'walsh', level: 23, type: 'symbol', sym: "H<sup>⊗n</sup>", name: "Walshova–Hadamardova transformácia", text: "H<sup>⊗n</sup>|x⟩ = 2<sup>−n/2</sup> Σ<sub>y</sub> (−1)<sup>x⋅y</sup>|y⟩, kde x⋅y je skalárny súčin mod 2. Z |0…0⟩ vytvorí rovnomernú superpozíciu všetkých 2ⁿ vstupov n hradlami.", dont: "Rovnomerná superpozícia neznamená, že výsledky všetkých vstupov vieme prečítať." },
  { id: 'djalg', level: 23, type: 'pojem', sym: "A(0…0)", name: "Deutschov–Jozsov algoritmus", text: "f: {0,1}ⁿ → {0,1} je sľúbene konštantná alebo vyvážená. Po H<sup>⊗n</sup>, orákule a H<sup>⊗n</sup> je amplitúda |0…0⟩ rovná 2<sup>−n</sup> Σ(−1)<sup>f(x)</sup>: ±1 pre konštantnú, 0 pre vyváženú. Jeden dotaz namiesto 2<sup>n−1</sup>+1.", dont: "Výhoda je oproti deterministickému klasickému algoritmu; pravdepodobnostný klasický stačí niekoľko dotazov." },
  { id: 'bvalg', level: 23, type: 'pojem', sym: "s ⋅ x", name: "Bernsteinov–Vaziraniho algoritmus", text: "f(x) = s ⋅ x mod 2 so skrytým reťazcom s. Ten istý obvod ako Deutsch–Jozsa: výsledok merania je priamo s. Kvantovo 1 dotaz, klasicky n dotazov (x = 100…, 010…, …)." },
  { id: 'querycost', level: 23, type: 'symbol', sym: "Q(f)", name: "zložitosť dotazov", text: "Meria sa počet volaní orákula, nie celkový čas. Kvantové výhody DJ a BV sú v tomto modeli; nehovoria nič o tom, ako rýchlo sa orákulum fyzicky vykoná.", dont: "Menej dotazov ≠ automaticky rýchlejší reálny výpočet." },
  { id: 'optctrl', level: 23, type: 'pojem', sym: "🎛", name: "optimálne riadenie (GRAPE)", text: "Hradlá sa na hardvéri (NMR, supravodiče) skladajú z tvarovaných pulzov. Optimalizačné metódy ako GRAPE hľadajú tvar pulzu, ktorý dá požadovaný unitár čo najpresnejšie a najrýchlejšie." },

  // ---------- Level 24: Mačací qubit (prednáška 8) ----------
  { id: 'mirrahimip', level: 24, type: 'osobnost', sym: "👤", name: "Mazyar Mirrahimi", text: "Francúzsko-iránsky matematik a fyzik (Inria Paris). V roku 2014 navrhol mačacie qubity chránené dvojfotónovou disipáciou — základ architektúry firmy Alice & Bob." },
  { id: 'catqubit', level: 24, type: 'pojem', sym: "🐈", name: "mačací qubit", text: "|0<sub>L</sub>⟩ ≃ |α⟩, |1<sub>L</sub>⟩ ≃ |−α⟩ — dva koherentné stavy mikrovlnného rezonátora. Prekryv ⟨α|−α⟩ = e<sup>−2|α|²</sup> rýchlo klesá s n̄ = |α|², takže stavy sú takmer ortogonálne.", dont: "Nie je to živá mačka — názov odkazuje na superpozíciu dvoch „makroskopicky“ odlišných stavov." },
  { id: 'biasnoise', level: 24, type: 'symbol', sym: "Γ<sub>bit</sub> ≪ Γ<sub>phase</sub>", name: "biasovaný šum", text: "Γ<sub>bit</sub> ∝ e<sup>−2n̄</sup> klesá exponenciálne, Γ<sub>phase</sub> ∝ n̄ rastie lineárne. Stačí potom opravovať len fázové chyby (1D opakovací alebo LDPC kód) — preto oveľa menej fyzických qubitov.", dont: "Fázové chyby nezmiznú, naopak s n̄ mierne rastú." },
  { id: 'twophoton', level: 24, type: 'symbol', sym: "κ₂ D[a² − α²]", name: "dvojfotónová disipácia", text: "dρ/dt = κ₂ D[a² − α²]ρ + κ₁ D[a]ρ. Prostredie odoberá fotóny po pároch a zároveň pumpuje; |±α⟩ sú stacionárne, ich obal je podpriestor bez dekoherencie ker(a² − α²) — rezervoárové inžinierstvo.", dont: "Disipácia tu nemeria, či je stav |α⟩ alebo |−α⟩ — preto nezničí superpozíciu." },
  { id: 'catstate', level: 24, type: 'symbol', sym: "|C±⟩", name: "mačacie stavy C±", text: "|C±⟩ = N±(|α⟩ ± |−α⟩), N± = 1/√(2(1 ± e<sup>−2|α|²</sup>)). C+ má párny, C− nepárny počet fotónov; strata fotónu ich zamení: a|C±⟩ ∝ |C∓⟩ — to je fázová chyba Z<sub>L</sub>." },
  { id: 'zeno', level: 24, type: 'pojem', sym: "🏹", name: "kvantový Zenónov jav", text: "Časté meranie zmrazí vývoj: P<sub>N</sub>(t) ≃ (1 − (ΔH)²t²/(N²ħ²))^N → 1. Zostane len H<sub>Z</sub> = PHP. Zenónovo hradlo: slabý pohon ε(a + a†) sa premietne na 2ħεα Z<sub>L</sub>, rotácia o θ = 4εαt.", dont: "Funguje vďaka kvadratickému správaniu pre krátke časy — nie je to „zastavenie času“." },
  { id: 'buffer', level: 24, type: 'pojem', sym: "a ↔ b", name: "pamäťový a bufferový rezonátor", text: "Pamäť a (dlhý život) a stratový buffer b (κ<sub>b</sub>) spojené pumpou ω<sub>p</sub> = |2ω<sub>a</sub> − ω<sub>b</sub>|: H<sub>int</sub> = ħg₂(a²b† + a†²b). Po eliminácii buffra vznikne κ₂ ≈ 4|g₂|²/κ<sub>b</sub>.", dont: "Buffer nekopíruje qubit (no-cloning) — len odnáša páry fotónov." },
];

